import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const matrix = JSON.parse(readFileSync(new URL('release/acceptance-matrix.json', root), 'utf8'));
const outputUrl = new URL(matrix.generated_document, root);
const labels = {
  planned: 'Planned', development: 'Beta', fixture_verified: 'Fixture verified',
  hardware_verified: 'Hardware verified', production: 'Production'
};
const groups = [...new Set(matrix.components.map((item) => item.group))];
const lines = [
  '# PulseScope Feature Status', '',
  '<!-- Generated by scripts/generate-feature-status.mjs. Edit release/acceptance-matrix.json instead. -->', '',
  `Release contract: **${matrix.release}**. This table distinguishes implemented code from fixture verification, physical hardware verification, and production readiness.`, '',
  'Beta items are intentionally visible in the normal UI when useful, but the UI must show their open acceptance gate. “Hardware verified” applies only to the named device evidence; Soapy compatibility is not a certification claim.', ''
];

for (const group of groups) {
  lines.push(`## ${group[0].toUpperCase()}${group.slice(1)}`, '', '| Feature | Status | Surface | Required | Open gate / acceptance criterion |', '|---|---|---|:---:|---|');
  for (const item of matrix.components.filter((entry) => entry.group === group)) {
    lines.push(`| ${item.name} | ${labels[item.status]} | ${item.visibility} | ${item.required ? 'yes' : 'no'} | ${item.acceptance_gate.replaceAll('|', '\\|')} |`);
  }
  lines.push('');
}

const generated = `${lines.join('\n').trim()}\n`;
if (process.argv.includes('--check')) {
  let current = '';
  try { current = readFileSync(outputUrl, 'utf8').replaceAll('\r\n', '\n'); } catch {}
  if (current !== generated) {
    console.error(`${matrix.generated_document} is stale; run pnpm generate:feature-status`);
    process.exit(1);
  }
  console.log(`${matrix.generated_document} matches the acceptance matrix`);
} else {
  writeFileSync(outputUrl, generated);
  console.log(`generated ${matrix.generated_document}`);
}
